// Builds the browser script the guide render runs (src/lib/shot/render-page.ts + engine + three) into src/lib/shot/render-bundle.generated.ts.
// Run: npm run shot:bundle. A unit test fails when the committed copy is stale.
import { build } from "esbuild";
import { writeFileSync } from "node:fs";
const r = await build({ entryPoints: ["src/lib/shot/render-page.ts"], bundle: true, write: false, format: "iife", platform: "browser", target: "es2020", minify: true, legalComments: "none" });
writeFileSync("src/lib/shot/render-bundle.generated.ts", `// GENERATED by scripts/shot-bundle.mjs from src/lib/shot/render-page.ts. Do not edit; run npm run shot:bundle.\nexport const SHOT_BUNDLE = ${JSON.stringify(r.outputFiles[0].text)};\n`);
console.log("shot bundle", Math.round(r.outputFiles[0].text.length / 1024), "KB");
